1	export type Cell = [number, number];
2	
3	function keyOf([x, y]: Cell): string {
4	  return `${x},${y}`;
5	}
6	
7	function neighborsOf([x, y]: Cell): Cell[] {
8	  const offsets = [-1, 0, 1];
9	  return offsets.flatMap((dx) =>
10	    offsets
11	      .filter((dy) => !(dx === 0 && dy === 0))
12	      .map((dy): Cell => [x + dx, y + dy]),
13	  );
14	}
15	
16	function isAlive(cell: Cell, liveKeys: Set<string>): boolean {
17	  return liveKeys.has(keyOf(cell));
18	}
19	
20	function countLiveNeighbors(cell: Cell, liveKeys: Set<string>): number {
21	  return neighborsOf(cell).filter((neighbor) => isAlive(neighbor, liveKeys))
22	    .length;
23	}
24	
25	function willBeAlive(
26	  isCurrentlyAlive: boolean,
27	  liveNeighborCount: number,
28	): boolean {
29	  return isCurrentlyAlive
30	    ? liveNeighborCount === 2 || liveNeighborCount === 3
31	    : liveNeighborCount === 3;
32	}
33	
34	export function nextGeneration(liveCells: Cell[]): Cell[] {
35	  const liveKeys = new Set(liveCells.map(keyOf));
36	  const candidates = new Map<string, Cell>(
37	    [...liveCells, ...liveCells.flatMap(neighborsOf)].map((cell) => [
38	      keyOf(cell),
39	      cell,
40	    ]),
41	  );
42	  return [...candidates.values()].filter((cell) =>
43	    willBeAlive(isAlive(cell, liveKeys), countLiveNeighbors(cell, liveKeys)),
44	  );
45	}
