    ? liveNeighborCount === CROWDED_BUT_SURVIVABLE_NEIGHBORS ||
        liveNeighborCount === REPRODUCTION_NEIGHBORS
    : liveNeighborCount === REPRODUCTION_NEIGHBORS;
}

